package com.yuegang.zhihui.training.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.training.security.*;import jakarta.servlet.http.*;import java.nio.charset.*;import java.nio.file.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.jdbc.core.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/training/documents")public final class TrainingDocumentDownloadController{private final JdbcTemplate jdbc;private final TrainingUserResolver users;private final Path root;public TrainingDocumentDownloadController(DataSource d,TrainingUserResolver u,@Value("${ygh.training.storage-root}")String r){jdbc=new JdbcTemplate(d);users=u;root=Path.of(r).toAbsolutePath().normalize();}@GetMapping("/{id}/content")ResponseEntity<Resource>content(@PathVariable String id,@RequestParam(defaultValue="true")boolean inline,HttpServletRequest r){long user=users.resolve(r),document=positive(id);var row=jdbc.query("SELECT d.file_name,d.media_type,d.storage_key,d.size_bytes,c.course_id FROM training_document d JOIN training_chapter c ON c.id=d.chapter_id WHERE d.id=? AND d.status='ACTIVE'",x->{if(!x.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new Row(x.getString(1),x.getString(2),x.getString(3),x.getLong(4),x.getLong(5));},document);Integer assigned=jdbc.queryForObject("SELECT COUNT(*) FROM training_assignment WHERE user_id=? AND course_id=?",Integer.class,user,row.course);if(assigned==null||assigned==0)users.requirePermission(r,"training:course:write");Path file=root.resolve(row.key).normalize();if(!file.startsWith(root)||!Files.isRegularFile(file))throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);Resource resource=new FileSystemResource(file);ContentDisposition disposition=(inline?ContentDisposition.inline():ContentDisposition.attachment()).filename(row.name,StandardCharsets.UTF_8).build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(row.media)).contentLength(row.size).header(HttpHeaders.CONTENT_DISPOSITION,disposition.toString()).header("X-Content-Type-Options","nosniff").body(resource);}private record Row(String name,String media,String key,long size,long course){}private static long positive(String x){try{long v=Long.parseLong(x);if(v<=0)throw new NumberFormatException();return v;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
